import { jsx as _jsx, jsxs as _jsxs } from "react/jsx-runtime";
import { describe, it, expect, vitest } from "vitest";
import { screen, render, within } from "@testing-library/react";
import { KpiContainer, Kpi } from "../index";
describe("KpiContainer - CARD", () => {
    it("Should render a simple KpiContainer correctly", () => {
        render(_jsx(KpiContainer, { variant: "CARD", children: [_jsx(Kpi, { label: "one", value: 123 }, "123")] }));
        expect(screen.getAllByTestId("kpi")).toHaveLength(1);
        expect(screen.getAllByTestId("paper")).toHaveLength(1);
        expect(screen.getByText("one")).toBeInTheDocument();
        expect(screen.getByText("123")).toBeInTheDocument();
    });
    it("Should render a simple KpiContainer correctly - using kpis", () => {
        render(_jsx(KpiContainer, { kpis: [
                {
                    label: "one",
                    value: 123,
                },
            ], variant: "CARD" }));
        expect(screen.getAllByTestId("kpi")).toHaveLength(1);
        expect(screen.getAllByTestId("paper")).toHaveLength(1);
        expect(screen.getByText("one")).toBeInTheDocument();
        expect(screen.getByText("123")).toBeInTheDocument();
    });
    it("should allow for childrenPerRow to be set", () => {
        render(_jsxs(KpiContainer, { childrenPerRow: 1, variant: "CARD", children: [_jsx(Kpi, { label: "one", value: 123 }), _jsx(Kpi, { label: "two", value: 456 }), _jsx(Kpi, { label: "three", value: 789 })] }));
        expect(screen.getAllByTestId("kpi")).toHaveLength(3);
        expect(screen.getAllByTestId("kpi-cards")).toHaveLength(3);
        expect(screen.getAllByTestId("paper")).toHaveLength(3);
        expect(within(screen.getAllByTestId("kpi-cards")[0]).getAllByTestId("kpi")).toHaveLength(1);
        expect(within(screen.getAllByTestId("kpi-cards")[1]).getAllByTestId("kpi")).toHaveLength(1);
        expect(within(screen.getAllByTestId("kpi-cards")[2]).getAllByTestId("kpi")).toHaveLength(1);
    });
    it("Should wrap KPIs in papers", () => {
        render(_jsxs(KpiContainer, { variant: "CARD", children: [_jsx(Kpi, { label: "one", value: 123 }), _jsx(Kpi, { label: "two", value: 456 }), _jsx(Kpi, { label: "three", value: 789 }), _jsx(Kpi, { label: "four", value: 1489 })] }));
        expect(screen.getAllByTestId("kpi")).toHaveLength(4);
        expect(screen.getAllByTestId("kpi-cards")).toHaveLength(1);
        expect(screen.getAllByTestId("paper")).toHaveLength(4);
        expect(screen.getByText("one")).toBeInTheDocument();
        expect(screen.getByText("123")).toBeInTheDocument();
        expect(screen.getByText("two")).toBeInTheDocument();
        expect(screen.getByText("456")).toBeInTheDocument();
        expect(screen.getByText("three")).toBeInTheDocument();
        expect(screen.getByText("789")).toBeInTheDocument();
        expect(screen.getByText("four")).toBeInTheDocument();
        expect(screen.getByText("1,489")).toBeInTheDocument();
    });
    it("Should wrap KPIs in papers and distribute them evenly (8 -> 4 - 4)", () => {
        render(_jsxs(KpiContainer, { variant: "CARD", children: [_jsx(Kpi, { label: "one", value: 123 }), _jsx(Kpi, { label: "two", value: 456 }), _jsx(Kpi, { label: "three", value: 789 }), _jsx(Kpi, { label: "four", value: 1489 }), _jsx(Kpi, { label: "five", value: 6123 }), _jsx(Kpi, { label: "six", value: 5456 }), _jsx(Kpi, { label: "seven", value: 2789 }), _jsx(Kpi, { label: "eight", value: 7489 })] }));
        expect(screen.getAllByTestId("kpi")).toHaveLength(8);
        expect(screen.getAllByTestId("kpi-cards")).toHaveLength(2);
        expect(screen.getAllByTestId("paper")).toHaveLength(8);
        expect(within(screen.getAllByTestId("kpi-cards")[0]).getAllByTestId("kpi")).toHaveLength(4);
        expect(within(screen.getAllByTestId("kpi-cards")[1]).getAllByTestId("kpi")).toHaveLength(4);
    });
    it("Should wrap KPIs in papers and distribute them evenly (8 -> 4 - 4) - using kpis", () => {
        render(_jsx(KpiContainer, { kpis: [
                {
                    label: "one",
                    value: 123,
                },
                {
                    label: "two",
                    value: 456,
                },
                {
                    label: "three",
                    value: 789,
                },
                {
                    label: "four",
                    value: 1489,
                },
                {
                    label: "five",
                    value: 6123,
                },
                {
                    label: "six",
                    value: 5456,
                },
                {
                    label: "seven",
                    value: 2789,
                },
                {
                    label: "eight",
                    value: 7489,
                },
            ], variant: "CARD" }));
        expect(screen.getAllByTestId("kpi")).toHaveLength(8);
        expect(screen.getAllByTestId("kpi-cards")).toHaveLength(2);
        expect(screen.getAllByTestId("paper")).toHaveLength(8);
        expect(within(screen.getAllByTestId("kpi-cards")[0]).getAllByTestId("kpi")).toHaveLength(4);
        expect(within(screen.getAllByTestId("kpi-cards")[1]).getAllByTestId("kpi")).toHaveLength(4);
    });
    it("A single row holds max 5 KPIs (9 -> 5 - 4)", () => {
        render(_jsxs(KpiContainer, { variant: "CARD", children: [_jsx(Kpi, { label: "one", value: 123 }), _jsx(Kpi, { label: "two", value: 456 }), _jsx(Kpi, { label: "three", value: 789 }), _jsx(Kpi, { label: "four", value: 1489 }), _jsx(Kpi, { label: "five", value: 6123 }), _jsx(Kpi, { label: "six", value: 5456 }), _jsx(Kpi, { label: "seven", value: 2789 }), _jsx(Kpi, { label: "eight", value: 7489 }), _jsx(Kpi, { label: "nine", value: 10000 })] }));
        expect(screen.getAllByTestId("kpi")).toHaveLength(9);
        expect(screen.getAllByTestId("kpi-cards")).toHaveLength(2);
        expect(screen.getAllByTestId("paper")).toHaveLength(9);
        expect(within(screen.getAllByTestId("kpi-cards")[0]).getAllByTestId("kpi")).toHaveLength(5);
        expect(within(screen.getAllByTestId("kpi-cards")[1]).getAllByTestId("kpi")).toHaveLength(4);
    });
});
describe("KpiContainer - BAR", () => {
    it("Should render a simple KpiContainer correctly (1 bar)", () => {
        render(_jsxs(KpiContainer, { variant: "BAR", children: [_jsx(Kpi, { label: "one", value: 123 }), _jsx(Kpi, { label: "two", value: 456 })] }));
        expect(screen.getAllByTestId("kpi")).toHaveLength(2);
        expect(screen.getAllByTestId("kpi-bar")).toHaveLength(1);
        expect(screen.getByText("one")).toBeInTheDocument();
        expect(screen.getByText("two")).toBeInTheDocument();
        expect(screen.getByText("123")).toBeInTheDocument();
        expect(screen.getByText("456")).toBeInTheDocument();
    });
    it("Should render a simple KpiContainer correctly (1 bar) - using kpis", () => {
        render(_jsx(KpiContainer, { kpis: [
                {
                    label: "one",
                    value: 123,
                },
                {
                    label: "two",
                    value: 456,
                },
            ], variant: "BAR" }));
        expect(screen.getAllByTestId("kpi")).toHaveLength(2);
        expect(screen.getAllByTestId("kpi-bar")).toHaveLength(1);
        expect(screen.getByText("one")).toBeInTheDocument();
        expect(screen.getByText("two")).toBeInTheDocument();
        expect(screen.getByText("123")).toBeInTheDocument();
        expect(screen.getByText("456")).toBeInTheDocument();
    });
    it("Should split the KPIs across bars evenly (8 -> 4 - 4)", () => {
        render(_jsxs(KpiContainer, { variant: "BAR", children: [_jsx(Kpi, { label: "one", value: 123 }), _jsx(Kpi, { label: "two", value: 456 }), _jsx(Kpi, { label: "three", value: 789 }), _jsx(Kpi, { label: "four", value: 101112 }), _jsx(Kpi, { label: "five", value: 131415 }), _jsx(Kpi, { label: "six", value: 161718 }), _jsx(Kpi, { label: "seven", value: 192021 }), _jsx(Kpi, { label: "eight", value: 222324 })] }));
        expect(screen.getAllByTestId("kpi-bar")).toHaveLength(2);
        expect(screen.getAllByTestId("kpi")).toHaveLength(8);
        expect(within(screen.getAllByTestId("kpi-bar")[0]).getAllByTestId("kpi")).toHaveLength(4);
        expect(within(screen.getAllByTestId("kpi-bar")[1]).getAllByTestId("kpi")).toHaveLength(4);
    });
    it("a single bar holds max 5 KPIs (9 -> 5 - 4)", () => {
        render(_jsxs(KpiContainer, { variant: "BAR", children: [_jsx(Kpi, { label: "one", value: 123 }), _jsx(Kpi, { label: "two", value: 456 }), _jsx(Kpi, { label: "three", value: 789 }), _jsx(Kpi, { label: "four", value: 101112 }), _jsx(Kpi, { label: "five", value: 131415 }), _jsx(Kpi, { label: "six", value: 161718 }), _jsx(Kpi, { label: "seven", value: 192021 }), _jsx(Kpi, { label: "eight", value: 222324 }), _jsx(Kpi, { label: "nine", value: 252627 })] }));
        expect(screen.getAllByTestId("kpi-bar")).toHaveLength(2);
        expect(screen.getAllByTestId("kpi")).toHaveLength(9);
        expect(within(screen.getAllByTestId("kpi-bar")[0]).getAllByTestId("kpi")).toHaveLength(5);
        expect(within(screen.getAllByTestId("kpi-bar")[1]).getAllByTestId("kpi")).toHaveLength(4);
    });
    it("should call onclick when the KPI child is clicked and has an onClick function", () => {
        const handleClick = vitest.fn();
        render(_jsx(KpiContainer, { variant: "BAR", children: [_jsx(Kpi, { label: "one", onClick: handleClick, value: 123 }, "1")] }));
        screen.getByTestId("kpi").click();
        expect(handleClick).toHaveBeenCalled();
    });
    it("should call onclick when the kpi passed as prop is clicked and has an onClick function", () => {
        const handleClick = vitest.fn();
        render(_jsx(KpiContainer, { kpis: [{ label: "one", onClick: handleClick, value: 123 }], variant: "BAR" }));
        screen.getByTestId("kpi").click();
        expect(handleClick).toHaveBeenCalled();
    });
});
